/**
 * Question generation for Phase 1 question types.
 */
import type { Competency, QuestionType, Word } from '../types';

export type Rng = () => number;

export interface ChoiceQuestion {
  kind: 'choice';
  type: 'en_to_ja_mc' | 'ja_to_en_mc';
  wordId: string;
  prompt: string;
  /** Secondary line under the prompt (e.g. part of speech). */
  promptDetail: string;
  options: string[];
  answerIndex: number;
}

export interface SpellingQuestion {
  kind: 'spelling';
  type: 'spelling';
  wordId: string;
  prompt: string;
  promptDetail: string;
  /** First letter and length hint, e.g. "c _ _ _ _ _". */
  hint: string;
}

export type Question = ChoiceQuestion | SpellingQuestion;

export const OPTION_COUNT = 4;

export function questionTypeFor(c: Competency): QuestionType {
  switch (c) {
    case 'recognition':
      return 'en_to_ja_mc';
    case 'recall':
      return 'ja_to_en_mc';
    case 'spelling':
      return 'spelling';
    default:
      throw new Error(`No Phase 1 question type for competency "${c}"`);
  }
}

export function primaryJa(w: Word): string {
  return w.senses[0]?.ja ?? '';
}

export function shuffle<T>(items: readonly T[], rng: Rng): T[] {
  const a = items.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j]!, a[i]!];
  }
  return a;
}

/**
 * Pick distractor words: never the target, never a word in the same synonym
 * group, never a word whose option text equals the answer text. Words with the
 * same part of speech are preferred so options cannot be eliminated by grammar.
 */
export function pickDistractors(
  target: Word,
  pool: readonly Word[],
  optionText: (w: Word) => string,
  count: number,
  rng: Rng,
): Word[] {
  const answerText = optionText(target);
  const eligible = pool.filter(
    (w) =>
      w.id !== target.id &&
      !(target.synonymGroup && w.synonymGroup === target.synonymGroup) &&
      optionText(w) !== answerText &&
      optionText(w).length > 0,
  );
  const samePos = shuffle(
    eligible.filter((w) => w.partOfSpeech === target.partOfSpeech),
    rng,
  );
  const otherPos = shuffle(
    eligible.filter((w) => w.partOfSpeech !== target.partOfSpeech),
    rng,
  );
  const chosen: Word[] = [];
  const seen = new Set<string>([answerText]);
  for (const w of [...samePos, ...otherPos]) {
    const text = optionText(w);
    if (seen.has(text)) continue;
    seen.add(text);
    chosen.push(w);
    if (chosen.length === count) break;
  }
  return chosen;
}

export function buildChoiceQuestion(
  type: 'en_to_ja_mc' | 'ja_to_en_mc',
  target: Word,
  pool: readonly Word[],
  rng: Rng,
): ChoiceQuestion {
  const optionText = type === 'en_to_ja_mc' ? primaryJa : (w: Word) => w.word;
  const distractors = pickDistractors(target, pool, optionText, OPTION_COUNT - 1, rng);
  if (distractors.length < OPTION_COUNT - 1) {
    throw new Error(`Not enough distractors for "${target.word}"`);
  }
  const options = shuffle([target, ...distractors], rng).map(optionText);
  const answerIndex = options.indexOf(optionText(target));
  return {
    kind: 'choice',
    type,
    wordId: target.id,
    prompt: type === 'en_to_ja_mc' ? target.word : primaryJa(target),
    promptDetail: target.partOfSpeech,
    options,
    answerIndex,
  };
}

export function spellingHint(word: string): string {
  return word
    .split('')
    .map((ch, i) => (i === 0 || ch === ' ' || ch === '-' ? ch : '_'))
    .join(' ');
}

export function buildSpellingQuestion(target: Word): SpellingQuestion {
  const en = target.senses[0]?.en;
  return {
    kind: 'spelling',
    type: 'spelling',
    wordId: target.id,
    prompt: primaryJa(target),
    promptDetail: en ? `${target.partOfSpeech}  ${en}` : target.partOfSpeech,
    hint: spellingHint(target.word),
  };
}

export function buildQuestion(type: QuestionType, target: Word, pool: readonly Word[], rng: Rng): Question {
  if (type === 'en_to_ja_mc' || type === 'ja_to_en_mc') return buildChoiceQuestion(type, target, pool, rng);
  if (type === 'spelling') return buildSpellingQuestion(target);
  throw new Error(`Question type "${type}" is not available yet`);
}
